24	// Loads app.js on an empty, readable list and returns the add form plus every list the app tried to save.
25	function loadApp() {
26	  const elements = {};
27	  const saved = [];
28	  const store = {
29	    readError: false,
30	    load() { return { todos: [], readError: false }; },
31	    save(todos) { saved.push(todos.map((t) => ({ ...t }))); return 'saved'; },
