// Bug: the customer picks a big backup, and while it is still being read picks a second, smaller one. The small one fills the
// empty list; the big one then replaced that list without asking, because it decided against the list as it was when picked.
// Importing must never replace a non-empty list without asking. Runs app/app.js unchanged in a vm, like app.test.js.
// Run: node --test
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const crypto = require('node:crypto');
const backup = require('../app/backup.js');

const appJs = fs.readFileSync(path.join(__dirname, '..', 'app', 'app.js'), 'utf8');

function fakeElement() {
  const listeners = {};
  const el = {
    textContent: '', innerHTML: '', hidden: false, value: '', className: '', dataset: {}, returnValue: '', open: false,
    append() {},
    querySelector(sel) { return (el.children[sel] ||= fakeElement()); },
    children: {},
    showModal() {
      if (el.open) throw new Error('InvalidStateError: dialog already open');
      el.open = true;
    },
    close(value) {
      el.open = false;
      el.returnValue = value;
      for (const fn of listeners.close || []) fn();
      listeners.close = [];
    },
    addEventListener(type, fn) { (listeners[type] ||= []).push(fn); },
  };
  return el;
}

// A file whose text() resolves only when the test calls finish().
function slowFile(todos) {
  let finish;
  const done = new Promise((resolve) => { finish = resolve; });
  const text = backup.toBackupText(todos);
  return { file: { size: text.length, text: () => done.then(() => text) }, finish };
}

const todo = (id) => ({ id, title: `Việc ${id}`, done: false, createdAt: 1 });
const tick = () => new Promise((resolve) => setImmediate(resolve));

function loadApp() {
  const elements = {};
  const replaced = [];
  const store = {
    readError: false,
    load() { return { todos: [], readError: false }; },
    save() { return 'saved'; },
    replace(todos) { replaced.push(todos); return 'saved'; },
  };
  const document = {
    querySelector(sel) { return (elements[sel] ||= fakeElement()); },
    querySelectorAll() { return []; },
    createElement() { return fakeElement(); },
  };
  vm.runInNewContext(appJs, { ...backup, store, document, crypto });
  const pick = (file) => {
    const input = document.querySelector('#import');
    input.files = [file];
    return input.onchange({ target: input });
  };
  return { pick, replaced, dialog: document.querySelector('#confirm') };
}

test('a slow import that finishes after a second import still asks before replacing the list', async () => {
  const { pick, replaced, dialog } = loadApp();
  const big = slowFile([todo('b1'), todo('b2'), todo('b3')]);
  const small = slowFile([todo('s1')]);

  const first = pick(big.file);
  const second = pick(small.file);
  small.finish();
  await tick();
  big.finish();
  await tick();

  // Whichever import lands first may fill the empty list without asking; the other must then ask.
  assert.equal(replaced.length, 1, 'only one import may replace without asking');
  assert.equal(dialog.open, true, 'the second replace must wait for the confirm dialog');

  dialog.close('');                // customer picks "Huỷ"
  await Promise.all([first, second]);
  assert.equal(replaced.length, 1, 'cancel writes nothing');
});

test('agreeing in the dialog lets the later import replace the list', async () => {
  const { pick, replaced, dialog } = loadApp();
  const big = slowFile([todo('b1'), todo('b2')]);
  const small = slowFile([todo('s1')]);

  const first = pick(big.file);
  const second = pick(small.file);
  big.finish();
  small.finish();
  await tick();
  await tick();

  assert.equal(dialog.open, true);
  dialog.close('yes');
  await Promise.all([first, second]);
  assert.equal(replaced.length, 2);
});

